# Compute first 10 primes
def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    import math
    r = int(math.isqrt(n))
    while i <= r:
        if n % i == 0:
            return False
        i += 2
    return True

primes = []
n = 2
while len(primes) < 10:
    if is_prime(n):
        primes.append(n)
    n += 1
primes, len(primes)
